    if(runner){check(product_entry||(result.at("actual_runner")==true&&(native_assembly?result.at("native_assembly")==true:result.at("models")==3)&&result.at("tool_turns")==2&&result.at("tool_events")==6&&result.at("final_assistant").get<std::string>()==history.back().json),"Actual AgentRunner must persist exactly its canonical final receipt");check(std::count_if(events.begin(),events.end(),[](const Event& event){return event.kind=="tool.started";})==3&&std::count_if(events.begin(),events.end(),[](const Event& event){return event.kind=="tool.failed";})==2&&std::count_if(events.begin(),events.end(),[](const Event& event){return event.kind=="tool.completed";})==1&&std::count_if(events.begin(),events.end(),[](const Event& event){return event.kind=="run.running";})==1&&(product_entry||std::count_if(events.begin(),events.end(),[](const Event& event){return event.kind.starts_with("model.");})==result.at("model_events").get<std::int64_t>()),"Actual AgentRunner startup, activity and model-event acknowledgements must not duplicate native facts");std::cout<<"Actual child AgentRunner read loop verified: queued startup, three backend model windows, two canonical tool turns, six native activity facts, one fresh filesystem read and canonical completion."<<std::endl;}
    if(product_entry)std::cout<<"Product worker entry verified in exact xmind child: single execution, private bootstrap, canonical completion and physical drain."<<std::endl;
    if(native_assembly&&!product_entry)std::cout<<"Native worker assembly verified in captured child: production journal, model gateway, read workspace, closed ports, backend controls and shared AgentRunner."<<std::endl;
    if(!runner)std::cout<<"Actual child backend context verified: previews withheld two reads, three native model windows matched guidance/history, one fresh read dispatched, twenty-four changed requests rejected."<<std::endl;
